"use client"

import animation from "react-useanimations/lib/cloudRain"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Cloud Rain" from https://useanimations.com (MIT): https://useanimations.com/icons/cloud-rain
export function AnimatedCloudRain(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover-replay"
      {...props}
    />
  )
}
